// priority: 40
// STODD Chrome @VERSION@ - endgame and midgame implants for Project: Edgerunner (server script).
// Generated by tools/gen_chrome.py from chrome/script_template.js: edit those, not this file.
//
// Palladium loads this script from the STODD Chrome jar (data/stodd_chrome/kubejs_scripts), next to Edgerunner's own. It
//   1. reads config/stodd/chrome.json (written with the defaults the first time): per implant on/off, its load and a strength
//      multiplier for everything it gives, and the numbers of the two special effects;
//   2. makes each implant's Palladium power (what it gives while installed; Edgerunner grants the power named like the item);
//   3. registers each implant with Edgerunner's Ripperdoc (global.registerCyberwareInstallComponent): body slot, load, power;
//   4. runs the two effects a power cannot: the Kerenzikov dodge and the Second Heart's cheat death.
(function () {
    var NS = 'stodd_chrome';
    var IMPLANTS = /*@IMPLANTS@*/[];
    var CONFIG_PATH = 'config/stodd/chrome.json';

    var DEFAULTS = {
        about: 'STODD Chrome: each implant can be switched off (enabled), given another load (Edgerunner capacity it takes) and made stronger or weaker (strength multiplies every bonus it gives). Changes apply on the next start or /reload.',
        dodgeChance: 0.2,
        dodgeCooldownSeconds: 3,
        secondHeartCooldownSeconds: 180,
        secondHeartHealth: 8,
        implants: {}
    };
    IMPLANTS.forEach(function (im) { DEFAULTS.implants[im.id] = { enabled: true, load: im.load, strength: 1.0 }; });

    function plain(v) {
        try { return v == null ? null : JSON.parse(JSON.stringify(v)); } catch (e) { return null; }
    }
    function num(v, d, lo, hi) {
        var n = Number(v);
        if (v === null || v === undefined || v === '' || !isFinite(n)) return d;
        return Math.max(lo, Math.min(hi, n));
    }

    function readConfig() {
        var cfg = JSON.parse(JSON.stringify(DEFAULTS));
        var raw = null;
        try { raw = plain(JsonIO.read(CONFIG_PATH)); } catch (e) { raw = null; }
        if (raw && typeof raw === 'object') {
            cfg.dodgeChance = num(raw.dodgeChance, cfg.dodgeChance, 0, 1);
            cfg.dodgeCooldownSeconds = num(raw.dodgeCooldownSeconds, cfg.dodgeCooldownSeconds, 0, 600);
            cfg.secondHeartCooldownSeconds = num(raw.secondHeartCooldownSeconds, cfg.secondHeartCooldownSeconds, 0, 86400);
            cfg.secondHeartHealth = num(raw.secondHeartHealth, cfg.secondHeartHealth, 1, 1000);
            var ri = raw.implants && typeof raw.implants === 'object' ? raw.implants : {};
            IMPLANTS.forEach(function (im) {
                var r = ri[im.id] && typeof ri[im.id] === 'object' ? ri[im.id] : {};
                var c = cfg.implants[im.id];
                if (r.enabled === false || r.enabled === 'false') c.enabled = false;
                c.load = Math.floor(num(r.load, c.load, 0, 10000));
                c.strength = num(r.strength, c.strength, 0, 100);
            });
        } else {
            try { JsonIO.write(CONFIG_PATH, DEFAULTS); } catch (e) { console.warn('[STODD Chrome] could not write ' + CONFIG_PATH + ': ' + e); }
        }
        return cfg;
    }

    var CFG = readConfig();

    // ------------------------------------------------------------------ the powers
    function powerOf(im, c) {
        var abilities = {};
        im.abilities.forEach(function (a, k) {
            var b = JSON.parse(JSON.stringify(a));
            if (b.type === 'palladium:attribute_modifier' || b.type === 'palladium:healing') b.amount = Number(b.amount) * c.strength;
            b.icon = NS + ':' + im.id;
            b.title = im.name;
            b.description = im.blurb;
            b.hidden = false;
            b.hidden_in_bar = true;
            b.list_index = k;
            b.conditions = { enabling: [{ type: 'palladium:true' }], unlocking: [] };
            abilities['chrome_' + k] = b;
        });
        return {
            name: im.name,
            icon: NS + ':' + im.id,
            persistent_data: true,
            background: 'minecraft:textures/block/polished_deepslate.png',
            ability_bar_texture: 'project_edgerunner:textures/gui/ability_bar.png',
            gui_display_type: 'list',
            abilities: abilities
        };
    }

    // ------------------------------------------------------------------ the Ripperdoc
    function register(cfg) {
        if (typeof global.registerCyberwareInstallComponent !== 'function') return false;
        IMPLANTS.forEach(function (im) {
            var c = cfg.implants[im.id];
            if (!c.enabled) return;
            var item = NS + ':' + im.id;
            try {
                if (typeof global.getCyberwareInstallComponentConfig === 'function' && global.getCyberwareInstallComponentConfig(item)) return;
                global.registerCyberwareInstallComponent({
                    item: item,
                    name: im.name,
                    type: im.slot,
                    body_slot: im.slot,
                    activation_mode: 'passive',
                    load_cost: c.load,
                    palladium_power: item,
                    install_message: im.name + ' installed.',
                    remove_message: im.name + ' removed.'
                });
            } catch (e) {
                console.error('[STODD Chrome] could not register ' + item + ' with the Ripperdoc: ' + e);
            }
        });
        return true;
    }

    // now if Edgerunner's registry is already there, else once every script has loaded (and again after a /reload, which
    // gives Edgerunner a fresh registry)
    register(CFG);
    ServerEvents.highPriorityData(function (event) {
        CFG = readConfig();
        IMPLANTS.forEach(function (im) {
            event.addJson(NS + ':palladium/powers/' + im.id, powerOf(im, CFG.implants[im.id]));
        });
        if (!register(CFG)) console.warn('[STODD Chrome] Project: Edgerunner\'s cyberware registry is missing: the implants cannot be installed');
    });
    ServerEvents.loaded(function (event) {
        if (!register(CFG)) console.warn('[STODD Chrome] Project: Edgerunner\'s cyberware registry is missing: the implants cannot be installed');
        else console.info('[STODD Chrome] @VERSION@: ' + IMPLANTS.length + ' implants registered with the Ripperdoc');
    });

    // ------------------------------------------------------------------ effects
    var Bridge = null;
    try { Bridge = Java.loadClass('com.edgerunner.cyberware.CyberwareScriptBridge'); } catch (e) { Bridge = null; }
    function installed(entity, id) {
        try { return Bridge != null && !!Bridge.hasInstalledItem(entity, NS + ':' + id); } catch (e) { return false; }
    }
    function isPlayer(e) {
        try { return e != null && e.isPlayer(); } catch (x) { return false; }
    }
    function ready(e, key, seconds) {
        var now = Date.now();
        try {
            var last = Number(e.persistentData.getLong(key));
            if (last > 0 && last <= now && now - last < seconds * 1000) return false;
            e.persistentData.putLong(key, now);
        } catch (x) { }
        return true;
    }
    function run(e, cmd) {
        try { e.server.runCommandSilent(cmd.split('{p}').join(String(e.username))); } catch (x) { }
    }

    // Kerenzikov Reflex Core: a chance to slip an attack from something (a mob, a player, a projectile), every few seconds at most
    EntityEvents.hurt(function (event) {
        var e = event.entity;
        if (!isPlayer(e)) return;
        var attacker = null, src = event.source;
        try { attacker = src.getEntity(); } catch (x) { attacker = null; }
        if (attacker == null) { try { attacker = src.getDirectEntity(); } catch (x) { attacker = null; } }
        if (attacker == null) { try { attacker = src.actual; } catch (x) { attacker = null; } }
        if (attacker == null) return;
        if (!installed(e, 'kerenzikov_reflex_core')) return;
        if (!(Math.random() < CFG.dodgeChance)) return;
        if (!ready(e, 'stodd_chrome_dodge', CFG.dodgeCooldownSeconds)) return;
        event.cancel();
        run(e, 'execute as {p} at @s run playsound minecraft:entity.illusioner.mirror_move player @a ~ ~ ~ 0.8 1.6');
        run(e, 'execute as {p} at @s run particle minecraft:electric_spark ~ ~1 ~ 0.4 0.6 0.4 0.2 24');
        try { e.setStatusMessage(Text.aqua('Kerenzikov: dodged!')); } catch (x) { }
    });

    // Second Heart: a killing blow leaves you standing, once every few minutes
    EntityEvents.death(function (event) {
        var e = event.entity;
        if (!isPlayer(e)) return;
        if (!installed(e, 'second_heart')) return;
        if (!ready(e, 'stodd_chrome_heart', CFG.secondHeartCooldownSeconds)) return;
        event.cancel();
        try { e.setHealth(CFG.secondHeartHealth); } catch (x) { }
        run(e, 'effect give {p} minecraft:resistance 6 1');
        run(e, 'effect give {p} minecraft:regeneration 6 1');
        run(e, 'effect give {p} minecraft:absorption 20 1');
        run(e, 'execute as {p} at @s run playsound minecraft:item.totem.use player @a ~ ~ ~ 0.8 1.3');
        run(e, 'execute as {p} at @s run particle minecraft:totem_of_undying ~ ~1 ~ 0.4 0.8 0.4 0.4 40');
        try { e.setStatusMessage(Text.red('Second Heart: you should be dead.')); } catch (x) { }
    });
})();
